insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_106_v1'
from (values
('127.765.d.1.A',3,'A planner notes that wide sidewalks, bike lanes and nearby shops lead more residents to walk. This relates:','["physical design to the functioning of the environment", "music to traffic laws", "paint colors to weather", "shoe sizes to roads"]'::jsonb,0,'Design shapes how places work.','original'),
('127.765.d.1.A',4,'Adding crosswalks and lighting near a school mainly improves:','["the school colors", "how safely people use the space", "the lunch menu", "the bell schedule"]'::jsonb,1,'Design affects safety.','original'),
('127.765.d.1.B',3,'A city studies traffic counts and population growth to decide how many lanes a new road will need in 20 years. This analyzes data relative to:','["last year''s parade", "a sports score", "present and future needs of a project", "a menu price"]'::jsonb,2,'Data guides planning.','original'),
('127.765.d.1.B',4,'Projected population growth is useful to planners because it helps them estimate:','["lunch prices", "past weather", "school colors", "future demand for services"]'::jsonb,3,'Forecasts drive capacity.','original'),
('127.765.d.1.C',3,'Before approving a new warehouse, a planner checks zoning rules, environmental laws and permit requirements. This assesses:','["legal aspects of regulatory compliance in planning", "recipe rules", "game rules", "fashion rules"]'::jsonb,0,'Plans must meet regulations.','original'),
('127.765.d.1.C',4,'A zoning ordinance controls:','["school calendars", "how land in an area may be used", "who may vote", "interest rates"]'::jsonb,1,'Zoning regulates land use.','original'),
('127.765.d.1.D',3,'A class reviews whether its mock public hearing followed the required notice, speaking time and recording rules. This evaluates a class activity with regard to:','["songs and dances", "colors and fonts", "regulations and procedures", "menus and drinks"]'::jsonb,2,'Check procedures were followed.','original'),
('127.765.d.1.D',4,'Public hearings usually require that residents receive:','["no records", "no information", "secret agendas", "advance notice and a chance to speak"]'::jsonb,3,'Notice and participation.','original'),
('127.765.d.1.E',3,'A student uses a map to mark parks, bus stops and flood zones and builds a chart showing the numbers. This performs:','["mapping and graphic functions", "dance steps", "sewing steps", "cooking steps"]'::jsonb,0,'Maps and graphics display data.','original'),
('127.765.d.1.E',4,'A map legend helps readers by:','["hiding the data", "explaining what the symbols mean", "changing the scale", "removing borders"]'::jsonb,1,'Legends decode symbols.','original'),
('127.765.d.1.F',3,'A planner predicts that a new rail line will change job access, clinic visits and social services in a neighborhood. This predicts the interaction between:','["weather, soil and rain", "music, art and dance", "the economy, transportation, health and human services", "sports, snacks and games"]'::jsonb,2,'Systems affect each other.','original'),
('127.765.d.1.F',4,'Better public transit can improve health outcomes by:','["lengthening commutes", "raising prices", "closing clinics", "helping people reach clinics and jobs"]'::jsonb,3,'Access to care and work.','original'),
('127.765.d.1.G',3,'A student attends a city council meeting and writes down which local, state and federal programs were discussed and how they affect residents. This documents:','["observations about government programs", "a cooking show", "a movie plot", "a sports game"]'::jsonb,0,'Documenting builds understanding.','original'),
('127.765.d.1.G',4,'Accurate notes from a public meeting should record:','["only jokes", "who said what and which decisions were made", "only attendance fees", "only the weather"]'::jsonb,1,'Capture facts and decisions.','original'),
('127.765.d.2.A',3,'A planning team lists new technologies, changing populations and funding limits as factors that will shape its work. This identifies:','["past scores", "old holidays", "emerging trends and barrier issues", "school colors"]'::jsonb,2,'Trends and barriers shape plans.','original'),
('127.765.d.2.A',4,'A barrier to implementing a city plan could be:','["public support", "a clear map", "good weather", "a lack of funding"]'::jsonb,3,'Funding is a common barrier.','original'),
('127.765.d.2.B',3,'When neighbors oppose a new bus route, the team practices negotiating and revising the route to reduce complaints. This practices:','["problem-solving techniques to overcome barriers", "ignoring problems", "stopping all plans", "blaming others"]'::jsonb,0,'Solve barriers with adaptation.','original'),
('127.765.d.2.B',4,'A good first step in solving a problem that blocks a plan is to:','["cancel the plan", "identify the cause of the problem", "assign blame", "ignore it"]'::jsonb,1,'Diagnose the cause.','original'),
('127.765.d.2.C',3,'A group compares making a plan through public votes, expert panels or small pilot tests and judges which fits its goals. This evaluates:','["styles of art", "styles of music", "the style of strategies for achieving goals", "styles of clothing"]'::jsonb,2,'Strategies differ in fit.','original'),
('127.765.d.2.C',4,'A pilot program lets planners test an idea:','["without any data", "only on paper", "after it fails citywide", "on a small scale before a full rollout"]'::jsonb,3,'Pilots reduce risk.','original'),
('127.765.d.3.A',3,'A student drafts a project proposal and gets the instructor''s approval of the scope before starting. This initiates a project by:','["securing approval of the project scope", "ignoring the teacher", "guessing at goals", "skipping the plan"]'::jsonb,0,'Initiation defines and approves scope.','original'),
('127.765.d.3.A',4,'The initiation stage of a project usually produces:','["a finished product", "a defined scope and approval to proceed", "a closing party", "the final report"]'::jsonb,1,'Scope and approval.','original'),
('127.765.d.3.B',3,'A team lists tasks, assigns people, sets deadlines and estimates costs before starting work. This plans:','["a shopping trip only", "a pep rally", "a project", "a lunch menu"]'::jsonb,2,'Planning organizes tasks and schedule.','original'),
('127.765.d.3.B',4,'A project schedule helps a team by:','["adding confusion", "removing deadlines", "hiding tasks", "showing tasks, owners and deadlines"]'::jsonb,3,'Schedules coordinate work.','original'),
('127.765.d.3.C',3,'While building a public survey, a student answers a classmate''s request for the question list and shares updates. This executes a project, including:','["responding to requests for information", "ignoring teammates", "stopping work", "hiding progress"]'::jsonb,0,'Execution includes communication.','original'),
('127.765.d.3.C',4,'During the execution phase, a team mainly:','["celebrates success", "carries out the planned tasks", "cancels the schedule", "writes the proposal"]'::jsonb,1,'Do the work.','original'),
('127.765.d.3.D',3,'A student tracks progress against the schedule, adjusts when a task slips and presents clear status updates to the class. This monitors and controls a project, including:','["silent work", "hidden results", "effective, cogent presentation of progress", "random updates"]'::jsonb,2,'Monitoring includes communicating status.','original'),
('127.765.d.3.D',4,'If a project task falls behind schedule, a manager should:','["ignore the delay", "blame a teammate", "drop the project", "adjust the plan and communicate the change"]'::jsonb,3,'Control means adapting.','original'),
('127.765.d.3.E',3,'At the end, a team delivers the final product, collects feedback, archives files and lists what it learned. This closes:','["a project", "a sports season only", "a lunch", "a window"]'::jsonb,0,'Closure includes lessons learned.','original'),
('127.765.d.3.E',4,'A lessons-learned review at project close helps teams:','["hide mistakes", "improve future projects", "delete records", "avoid reporting"]'::jsonb,1,'Learn for next time.','original'),
('127.765.d.3.F',3,'When a teammate is upset in a tense group meeting, the student stays calm, listens and keeps the discussion on track. This maintains:','["avoidance", "anger", "professionalism in challenging situations", "rudeness"]'::jsonb,2,'Stay calm and respectful.','original'),
('127.765.d.3.F',4,'In a heated one-on-one disagreement, the most professional approach is to:','["walk out without a word", "shout", "spread rumors", "listen and respond calmly"]'::jsonb,3,'Calm response.','original'),
('127.765.d.4.A',3,'A student pulls arguments and figures from a library database and trusted websites and judges how strong they are. This extracts and evaluates ideas from:','["research library resources and online materials", "social gossip", "lunch menus", "sports radio"]'::jsonb,0,'Evaluate sources.','original'),
('127.765.d.4.A',4,'A reliable online source for research is generally one that:','["has no author", "cites evidence and names its authors", "makes unsupported claims", "is anonymous"]'::jsonb,1,'Credibility check.','original'),
('127.765.d.4.B',3,'In a mock campaign class, students write questions, schedule sessions and role-play interviewing each other. This organizes and conducts:','["lunch breaks", "gym drills", "practice interviews", "school plays"]'::jsonb,2,'Practice builds interview skill.','original'),
('127.765.d.4.B',4,'Open-ended interview questions are useful because they:','["reduce information", "stop discussion", "require yes or no", "invite detailed answers"]'::jsonb,3,'Open questions elicit detail.','original'),
('127.765.d.4.C',3,'A student merges survey results, interview quotes and verified statistics into a report he designed himself. This compiles:','["original data and reliable source information into an objective report", "rumors into a post", "guesses into a chart", "opinions into a slogan"]'::jsonb,0,'Objective reports combine evidence.','original'),
('127.765.d.4.C',4,'An objective report should present information that is:','["one-sided", "accurate and balanced", "exaggerated", "unverified"]'::jsonb,1,'Objectivity matters.','original'),
('127.765.d.5.A',3,'A speaker appeals to logic, emotion and credibility, the classical patterns, and also uses modern storytelling. This analyzes and implements:','["recipes", "maps", "classical and modern patterns of rhetoric", "scores"]'::jsonb,2,'Rhetoric structures persuasion.','original'),
('127.765.d.5.A',4,'In rhetoric, an appeal to logic is called:','["ethos", "kairos", "pathos", "logos"]'::jsonb,3,'Logos = logic.','original'),
('127.765.d.5.B',3,'A debate team studies how different political, social and philosophical outlooks see the same issue. This analyzes:','["differing political, social, ideological and philosophical perspectives", "identical views", "a single viewpoint", "no views"]'::jsonb,0,'Perspectives differ.','original'),
('127.765.d.5.B',4,'Understanding multiple perspectives helps advocates:','["ignore opponents", "anticipate counterarguments", "avoid research", "avoid persuasion"]'::jsonb,1,'Know the other side.','original'),
('127.765.d.5.C',3,'A student checks whether a claim that crime fell 30% uses the right timeframe and source. This critiques:','["a logo''s color", "a song''s beat", "facts and statistical claims for accuracy and relevance", "a poem''s rhyme"]'::jsonb,2,'Check claims.','original'),
('127.765.d.5.C',4,'Before sharing a statistic in a speech, a speaker should:','["assume it''s true", "skip the source", "round it up", "verify the source and context"]'::jsonb,3,'Verify first.','original'),
('127.765.d.5.D',3,'A team removes a misleading photo and credits every source before handing out a campaign flyer. This ensures:','["materials meet ethical standards", "materials are longer", "materials are cheaper", "materials look flashy"]'::jsonb,0,'Ethical materials are honest and credited.','original'),
('127.765.d.5.D',4,'An ethical campaign flyer should avoid:','["accurate facts", "false or misleading claims", "credited sources", "clear contact info"]'::jsonb,1,'Don''t mislead.','original'),
('127.765.d.6.A',3,'In a mock council meeting, a student maps what a landlord, a tenant group and the city each want and how their representatives speak for them. This compares:','["bus routes", "sports teams", "interests of individuals, groups and their representatives", "breakfast items"]'::jsonb,2,'Interests differ.','original'),
('127.765.d.6.A',4,'A constituent is best described as:','["a judge", "a clerk", "a lobbyist", "a person represented by an elected official"]'::jsonb,3,'Constituents are represented.','original'),
('127.765.d.6.B',3,'A class designs a project to help students understand neighbors with different backgrounds and beliefs. This explores options for:','["promoting tolerance toward individuals and groups", "isolating groups", "ignoring differences", "promoting conflict"]'::jsonb,0,'Tolerance supports civic life.','original'),
('127.765.d.6.B',4,'One way to promote tolerance in a community is to:','["avoid contact", "hold events where different groups meet and talk", "limit speech", "spread stereotypes"]'::jsonb,1,'Contact builds understanding.','original'),
('127.765.d.6.C',3,'Two classmates disagree about a project plan, so a neutral student helps both explain their view and find a compromise. This employs:','["gossip techniques", "bullying techniques", "mediation techniques", "avoidance techniques"]'::jsonb,2,'Mediation uses neutral facilitation.','original'),
('127.765.d.6.C',4,'A mediator is someone who:','["ends the talks", "decides who wins", "joins one side", "helps parties reach agreement without taking sides"]'::jsonb,3,'Neutral facilitator.','original'),
('127.765.d.6.D',3,'As a debate stalls, a student offers a middle option that gives both groups something they want. This suggests:','["alternative proposals that keep discussions from collapsing", "assigning blame", "ending talks", "raising voices"]'::jsonb,0,'Alternatives keep talks moving.','original'),
('127.765.d.6.D',4,'A compromise proposal usually:','["gives one side everything", "gives each side part of what it wants", "ends the discussion", "ignores everyone"]'::jsonb,1,'Compromise balances interests.','original'),
('127.765.d.6.E',3,'A city posts agendas, minutes and budgets online so residents can see how decisions are made. This discusses methods of:','["hidden votes", "closed doors", "openness in decision-making processes", "secrecy in planning"]'::jsonb,2,'Transparency builds trust.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_106_v1'
from (values
('127.765.d.6.E',4,'Posting meeting minutes online increases:','["cost only", "secrecy", "confusion", "public transparency"]'::jsonb,3,'Open records.','original'),
('127.765.d.7.A',3,'A student builds a speech for a new youth center, using evidence, a clear request and a strong close. This delivers:','["a compelling argument regarding a proposal", "a joke list", "a silent poster", "a rambling story"]'::jsonb,0,'Compelling arguments use evidence and structure.','original'),
('127.765.d.7.A',4,'A compelling argument should include:','["loud volume only", "a clear claim supported by evidence", "no structure", "only opinion"]'::jsonb,1,'Claim + evidence.','original'),
('127.765.d.7.B',3,'A team creates a short video and slide deck to explain a proposed park project to council members. This creates:','["blank posters", "unreadable slides", "effective media presentations and projects", "random clips"]'::jsonb,2,'Media should inform clearly.','original'),
('127.765.d.7.B',4,'An effective slide for a council presentation should:','["hide the main point", "use tiny fonts", "be crowded with text", "be clear, concise and focused on one idea"]'::jsonb,3,'Clarity wins.','original'),
('127.765.d.7.C',3,'During a mock hearing, a student notices a skeptical audience and changes the pace and examples. This employs workplace skills to:','["observe reactions and adjust accordingly", "ignore the audience", "read faster", "end the talk"]'::jsonb,0,'Read the room.','original'),
('127.765.d.7.C',4,'If the audience looks confused during a presentation, the presenter should:','["stop speaking", "slow down and clarify", "insult them", "speed up"]'::jsonb,1,'Adjust to audience.','original'),
('127.765.d.7.D',3,'A volunteer coordinator recognizes effort, sets clear goals and asks for input to keep staff engaged. This evaluates and employs:','["ways to confuse staff", "ways to discourage staff", "techniques for motivating staff", "ways to ignore staff"]'::jsonb,2,'Motivation techniques.','original'),
('127.765.d.7.D',4,'Recognizing good work publicly is likely to:','["hide results", "create conflict", "decrease morale", "increase staff motivation"]'::jsonb,3,'Recognition motivates.','original'),
('127.765.d.7.E',3,'A team writes a checklist that requires disclosing conflicts of interest and crediting sources at each project step. This creates:','["project steps for avoiding ethical pitfalls", "steps for hiding errors", "steps for avoiding work", "steps for avoiding tasks"]'::jsonb,0,'Build ethics into process.','original'),
('127.765.d.7.E',4,'Disclosing a conflict of interest is a step that helps a team:','["speed up bias", "maintain trust and fairness", "create secrecy", "hide decisions"]'::jsonb,1,'Disclosure supports ethics.','original'),
('127.766.d.1.A',3,'A student leader sets clear goals, objectives and steps for a unit''s simulated mission and checks them against the organization''s mission. This explores and plans:','["a travel photo", "lunch plans", "goals and objectives of an organization within a mission", "a playlist"]'::jsonb,2,'Planning aligns goals with mission.','original'),
('127.766.d.1.A',4,'Objectives are most useful when they are:','["hidden", "vague", "endless", "specific and measurable"]'::jsonb,3,'SMART-style objectives.','original'),
('127.766.d.1.B',3,'A commander matches team members'' skills to the tasks a mission requires, such as linguist, analyst or medic. This creates personnel assignments that:','["align with job demands within a plan", "ignore skills", "avoid planning", "assign at random"]'::jsonb,0,'Right person for the role.','original'),
('127.766.d.1.B',4,'Assigning people to tasks that match their training helps a unit:','["lower morale", "perform more effectively", "cause delays", "waste skills"]'::jsonb,1,'Fit boosts performance.','original'),
('127.766.d.1.C',3,'A student studies how performance reviews, standards and feedback are used to rate members in a service. This explores:','["methods for painting walls", "how to cook", "processes used to implement evaluation systems and standards", "how to play games"]'::jsonb,2,'Evaluation systems rely on standards.','original'),
('127.766.d.1.D',3,'A class reviews counseling, mentoring and training programs available to service members and how to use them well. This explores and reviews:','["music charts", "sports scores", "menu plans", "the usage of available counseling and training resources"]'::jsonb,3,'Resources support personnel.','original'),
('127.766.d.2.A',3,'A student charts what local police, state agencies, federal forces and international partners are allowed to do in a joint response. This identifies:','["rules of engagement for agencies at different levels", "rules for board games", "rules for dances", "rules for cooking"]'::jsonb,0,'ROE define limits of action.','original'),
('127.766.d.2.A',4,'Rules of engagement are meant to:','["remove all limits", "define when and how force may be used", "encourage random action", "hide orders"]'::jsonb,1,'ROE control force.','original'),
('127.766.d.2.B',3,'A class reads the Geneva Conventions and treaties on treatment of prisoners and civilians and judges how they apply to a mission. This evaluates:','["school dress codes", "traffic signs only", "U.S. and international laws, treaties and conventions applicable to missions", "local menu laws"]'::jsonb,2,'Law of armed conflict applies.','original'),
('127.766.d.2.B',4,'The Geneva Conventions mainly protect:','["stock traders", "tourists", "sports fans", "wounded soldiers, prisoners and civilians in war"]'::jsonb,3,'Humanitarian protections.','original'),
('127.766.d.2.C',3,'A trainer tests slides, videos and drills with trainees and revises the weak ones. This employs and evaluates:','["effective training materials", "random handouts", "confusing slides", "unrelated videos"]'::jsonb,0,'Test training materials.','original'),
('127.766.d.2.D',3,'After a scenario about treating a captured combatant, students talk through right and wrong choices. This facilitates group discussion of:','["lunch choices", "ethical issues raised by current events", "fashion", "weather"]'::jsonb,1,'Ethics discussions build judgment.','original'),
('127.766.d.2.E',3,'A student audits a mock operation''s records to see if it followed military orders, international rules and agency procedures. This investigates:','["compliance with art", "compliance with fashion", "compliance with procedures and laws", "compliance with cooking"]'::jsonb,2,'Audits check compliance.','original'),
('127.766.d.2.F',3,'Using a new court ruling on surveillance, a student adjusts a sample plan to follow it. This applies:','["weather maps", "sports rules", "old jokes", "current rulings and regulatory laws to appropriate situations"]'::jsonb,3,'Apply current law.','original'),
('127.766.d.2.G',3,'In a case study, a student spots that an agent searched private records without a warrant. This recognizes and evaluates:','["actions in violation of laws, rules and standards", "actions in games", "actions in dance", "actions in sports"]'::jsonb,0,'Identify violations.','original'),
('127.766.d.2.G',4,'A search of private property without legal authority is an example of a:','["legal requirement", "violation of law and standards", "best practice", "standard procedure"]'::jsonb,1,'Warrantless search violates standards.','original'),
('127.766.d.3.A',3,'In a tabletop exercise, a team reads what its orders allow and forbid before acting. This explores:','["the music class", "the lunch hour", "the scope and limits of an assigned mission in a simulation", "the school bus route"]'::jsonb,2,'Know the scope.','original'),
('127.766.d.3.B',3,'A class assesses weather, local hostility, cultural friction and enemy capabilities in a simulated deployment. This evaluates:','["fashion trends", "soda flavors", "ticket prices", "physical, psychological, cultural and military threats"]'::jsonb,3,'Threat assessments are multi-dimensional.','original'),
('127.766.d.3.C',3,'Analysts study a rival government''s statements and actions to judge what it wants. This defines:','["the specific goals and intentions of foreign entities relevant to a mission", "a weather forecast", "a recipe", "a sports playbook"]'::jsonb,0,'Intent analysis informs missions.','original'),
('127.766.d.3.D',3,'A student reviews terrain, climate, waterways and borders of a region where conflict could break out in the future. This analyzes:','["songs", "physical characteristics of areas that could become battlegrounds", "colors of flags", "menus"]'::jsonb,1,'Terrain matters.','original'),
('127.766.d.3.E',3,'A class reads about radar, satellites, drones and patrols used to watch land and sea. This explores methods used to direct:','["lunchroom supervision", "playground games", "ground and sea surveillance", "bus pickup"]'::jsonb,2,'Surveillance methods.','original'),
('127.766.d.3.F',3,'A signals trainee learns how radio traffic is picked up and decoded in lawful intelligence work. This explores methods used to:','["sell phone plans", "send birthday cards", "edit videos", "intercept foreign military communications"]'::jsonb,3,'Signals intelligence.','original'),
('127.766.d.3.G',3,'A joint exercise trains analysts to share findings with partner security agencies using secure channels. This explores methods to:','["coordinate information with other national security agencies", "send chain letters", "share recipes", "post gossip"]'::jsonb,0,'Interagency coordination.','original'),
('127.766.d.3.G',4,'Information sharing among security agencies should use:','["public posts", "approved secure channels", "casual chat", "personal email"]'::jsonb,1,'Protect classified data.','original'),
('127.766.d.4.A',3,'A student labels and logs documents, photos and call records so an analyst can see whether a threat is real. This organizes:','["recipe cards", "sports gear", "evidence to facilitate discovery of a potentially hostile nature", "party favors"]'::jsonb,2,'Organized evidence supports analysis.','original'),
('127.766.d.4.B',3,'A team reviews how an agency and the nation responded to a suspicious foreign act and what could be improved. This evaluates:','["lunch lines", "a school dance", "a field trip", "agency and national actions of a potentially hostile nature"]'::jsonb,3,'Evaluate responses.','original'),
('127.766.d.5.A',3,'A student drafts a plan for a drill that covers an attack as well as an accidental chemical leak. This creates plans for response to:','["both hostile and unintended events", "only hostile events", "only weather", "only holidays"]'::jsonb,0,'All-hazards planning.','original'),
('127.766.d.5.B',3,'A trainee lists masks, medical kits and communications gear needed for different emergencies. This explores and evaluates:','["game consoles", "safety equipment and supplies needed for protection", "lunch boxes", "fashion gear"]'::jsonb,1,'Equipment planning.','original'),
('127.766.d.5.C',3,'A class reviews threat reports to decide whether a risk is serious enough to warrant a response. This evaluates:','["menus", "scoreboards", "available intelligence information for determining threat level", "recipes"]'::jsonb,2,'Use intel to rate threats.','original'),
('127.766.d.5.D',3,'A student builds a dashboard that tracks public alerts and news feeds about threats. This creates:','["a toy robot", "a skateboard", "a birthday card", "a device or project for monitoring local and global intelligence"]'::jsonb,3,'Monitoring tools aid awareness.','original'),
('127.766.d.5.E',3,'A simulation team practices staying in contact with federal agencies when local networks fail. This discusses methods to:','["maintain communications with federal agencies", "avoid contact", "stay silent", "delay reports"]'::jsonb,0,'Communication continuity.','original'),
('127.766.d.5.F',3,'A class lists risks such as hacking, weak passwords and open ports and ways to protect a network. This identifies and reviews issues in:','["school lunch menus", "the security and safety of network systems", "sports uniforms", "art supplies"]'::jsonb,1,'Cybersecurity issues.','original'),
('127.766.d.6.A',3,'Before designing a course, trainers study what a mission requires and what skills trainees lack. This explores:','["colors for classrooms", "menus for trainees", "methods used to analyze missions for which training is needed", "songs for drills"]'::jsonb,2,'Needs analysis first.','original'),
('127.766.d.6.B',3,'A staff compares the results of an older classroom method with a newer simulation and decides what to keep. This plans and evaluates:','["sports scores", "playlists", "fashion trends", "current and past training methods"]'::jsonb,3,'Compare methods.','original'),
('127.766.d.6.C',3,'A student reviews how trainers use tests, observation checklists and performance drills to track trainees'' progress. This reviews how agencies devise ways of:','["evaluating trainee progress", "buying snacks", "planning parades", "picking uniforms"]'::jsonb,0,'Evaluate trainees.','original'),
('127.766.d.1.C',4,'A rating system works fairly only if every member is judged against:','["personal friendships", "the same published standards", "secret criteria", "each rater''s mood"]'::jsonb,1,'Fair evaluation uses common standards.','original'),
('127.766.d.1.D',4,'A service member who is struggling after a hard deployment could use:','["hiding the problem", "quitting training", "available counseling and support resources", "avoiding help"]'::jsonb,2,'Resources exist to help personnel.','original'),
